use super::*;
async fn receive(channel:&File)->anyhow::Result<VerificationWorkerPacket>{let socket=channel.try_clone()?;tokio::task::spawn_blocking(move||verification_worker_receive(&socket)).await?.map_err(anyhow::Error::from)}
async fn receive_original_live(channel:&File,handoff:&HistoricalReadonlyChildHandoff,source:&mut StoppedHistoricalVerificationSource<'_>,child:&mut std::process::Child)->anyhow::Result<VerificationWorkerPacket>{
 let timeout=libc::timeval{tv_sec:2,tv_usec:0};anyhow::ensure!(unsafe{libc::setsockopt(channel.as_raw_fd(),libc::SOL_SOCKET,libc::SO_RCVTIMEO,(&timeout as *const libc::timeval).cast(),std::mem::size_of_val(&timeout)as libc::socklen_t)}==0,"Historical receive observation configuration failed");
 let deadline=std::time::Instant::now()+std::time::Duration::from_secs(120);
 loop{source.fence().await?;handoff.fence()?;match receive(channel).await{Ok(packet)=>{source.fence().await?;handoff.fence()?;return Ok(packet)},Err(error)if error.downcast_ref::<io::Error>().is_some_and(|e|matches!(e.kind(),io::ErrorKind::WouldBlock|io::ErrorKind::TimedOut))=>{anyhow::ensure!(child.try_wait()?.is_none(),"Original historical child exited without queued exact ACK");anyhow::ensure!(std::time::Instant::now()<deadline,"Original historical child exact ACK not observed within bounded120s; no readiness inferred");},Err(error)=>return Err(error)}}
}
fn ack(packet:VerificationWorkerPacket,handoff:&HistoricalReadonlyChildHandoff,child:&std::process::Child,phase:&str)->anyhow::Result<HistoricalReadonlyChildAck>{
 anyhow::ensure!(packet.credentials.pid==child.id()as i32&&packet.credentials.uid==unsafe{libc::geteuid()}&&packet.credentials.gid==unsafe{libc::getegid()}&&packet.files.is_empty(),"Historical parent observed wrong original child peer");let ack:HistoricalReadonlyChildAck=serde_json::from_slice(&packet.bytes)?;anyhow::ensure!(ack.version==1&&ack.nonce==handoff.wire.nonce&&ack.phase==phase&&ack.pid==child.id()as i32&&ack.uid==unsafe{libc::geteuid()}&&ack.executable_sha256==handoff.wire.executable_sha256&&ack.projection_sha256==handoff.wire.projection_sha256&&ack.listener_identity==handoff.wire.listener_identity,"Historical original child ACK purpose/ELF/listener/projection differs");handoff.fence()?;Ok(ack)
}
